    const lPrime = parsed.l + .3963377774 * a + .2158037573 * b;
    const mPrime = parsed.l - .1055613458 * a - .0638541728 * b;
    const sPrime = parsed.l - .0894841775 * a - 1.291485548 * b;
    const l = lPrime ** 3;
    const m = mPrime ** 3;
    const s = sPrime ** 3;
